{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Services</title>
  <style>
    :root{--bg:#fbfaf7;--accent:#6b8a6b;--muted:#6b6b6b;--card:#fff;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#222;background:linear-gradient(180deg,var(--bg),#f3f5f2)}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:transparent}
    .brand{display:flex;gap:14px;align-items:center}
    .logo{width:56px;height:56px;border-radius:12px;background:linear-gradient(135deg,var(--accent),#8fb98f);display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{margin-left:16px;color:var(--muted);text-decoration:none;font-weight:600}
    .hero{padding:40px 28px;display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:start}
    .hero-card{background:var(--card);border-radius:12px;padding:26px;box-shadow:0 8px 30px rgba(20,30,20,0.06)}
    h1{margin:0 0 10px 0;font-size:26px}
    p.lead{margin:0;color:var(--muted)}
    .meta{font-size:13px;color:var(--muted);margin-top:12px}
    .cta{display:inline-block;margin-top:18px;padding:10px 16px;background:var(--accent);color:white;border-radius:10px;text-decoration:none;font-weight:700}

    /* Pattern block using embedded SVG data-uri for subtle texture */
    .pattern-bg{background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='240' height='240' viewBox='0 0 240 240'><defs><pattern id='p' width='24' height='24' patternUnits='userSpaceOnUse'><rect width='24' height='24' fill='%23f8fbf8'/><path d='M0 12h24' stroke='%23dfeee0' stroke-width='0.8'/><path d='M12 0v24' stroke='%23dfeee0' stroke-width='0.8'/></pattern></defs><rect width='240' height='240' fill='url(%23p)'/></svg>");border-radius:12px;padding:18px}

    .list{display:flex;flex-direction:column;gap:12px;margin-top:16px}
    .service{display:flex;gap:12px;align-items:flex-start}
    .dot{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#e9f5ea,#ffffff);display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--accent)}
    .svc-title{font-weight:700;margin:0}
    .svc-desc{margin:4px 0 0 0;color:var(--muted);font-size:14px}

    .aside-note{font-size:13px;color:var(--muted);margin-top:14px}
    footer{padding:28px;border-top:1px solid #eef2ea;margin-top:28px;color:var(--muted);display:flex;justify-content:space-between}

    /* FAQ */
    .faq{margin-top:18px;display:grid;grid-template-columns:1fr 1fr;gap:12px}
    .faq-item{background:var(--card);padding:12px;border-radius:10px}
    .faq-item h4{margin:0 0 8px 0;font-size:15px}
    .faq-item p{margin:0;color:var(--muted);font-size:13px}

    /* small utilities */
    .kb{font-size:13px;color:var(--muted)}
    @media(max-width:880px){.hero{grid-template-columns:1fr;}.hero-card{order:0}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">A</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Custom Blends</a>
      <a href="shop.html">Essentials Shop</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach Out</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="hero-card pattern-bg">
        <h1>Practitioner-led aromatherapy sessions that may support mindful shifts</h1>
        <p class="lead">Small gatherings and one-on-one consultations focused on scent practices you can return to. Sessions emphasize safety, clarity, and intentional blending.</p>
        <div class="meta">Sessions and events take place in-person and remotely. All work respects safety guidelines: dilution, patch testing, and contraindication checks are standard.</div>

        <div class="list">
          <div class="service">
            <div class="dot">1</div>
            <div>
              <p class="svc-title">Short Consult — 45 min</p>
              <p class="svc-desc">A focused intake and a single-support blend you can use for a week. May support short-term calm or focus.</p>
            </div>
          </div>

          <div class="service">
            <div class="dot">2</div>
            <div>
              <p class="svc-title">Rhythm Session — 90 min</p>
              <p class="svc-desc">Deeper intake, education on safe use, and a tailored blend. Includes dilution guidance and patch-test plan.</p>
            </div>
          </div>

          <div class="service">
            <div class="dot">3</div>
            <div>
              <p class="svc-title">Group Workshop</p>
              <p class="svc-desc">A curated, hands-on session for small groups focused on scent literacy and creating simple supportive rituals.</p>
            </div>
          </div>
        </div>

        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>

      <aside class="hero-card">
        <h3 style="margin-top:0">What to expect</h3>
        <p class="kb">Each offering comes with a clear safety briefing. We'll cover dilution ratios, storage, patch testing, and notes about pets and pregnancy. Nothing shared here replaces medical advice.</p>

        <div class="aside-note">
          <strong>Ready to book?</strong>
          <div style="margin-top:8px"><a class="cta" href="book.html">Reserve a session</a></div>
        </div>
      </aside>
    </section>

    <section style="padding:18px 28px">
      <h2 style="margin-top:0">Myths vs. Practical Truths</h2>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
        <div style="background:var(--card);padding:12px;border-radius:10px">
          <h4 style="margin:0 0 8px 0">Myth: Essential oils cure illness</h4>
          <p class="kb">Truth: Aromatherapy may support wellbeing but is not a substitute for medical care. We focus on supportive, safety-first practices.</p>
        </div>
        <div style="background:var(--card);padding:12px;border-radius:10px">
          <h4 style="margin:0 0 8px 0">Myth: More is better</h4>
          <p class="kb">Truth: We emphasize conservative dilution and testing, especially for children, pets, and during pregnancy.</p>
        </div>
      </div>
    </section>

    <section style="padding:18px 28px">
      <h2>Foundational Principles</h2>
      <div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:12px">
        <div style="flex:1 1 220px;background:var(--card);padding:12px;border-radius:10px">Safety-first: dilution, patch test, and clear usage instructions.</div>
        <div style="flex:1 1 220px;background:var(--card);padding:12px;border-radius:10px">Evidence-aware: we use fragrance and botanical literacy without making medical claims.</div>
        <div style="flex:1 1 220px;background:var(--card);padding:12px;border-radius:10px">Repeatable rituals: practices you can integrate into your day.</div>
      </div>
    </section>

    <section style="padding:18px 28px">
      <h2>Notes from sessions</h2>
      <div style="display:grid;gap:10px">
        <div style="background:var(--card);padding:12px;border-radius:10px">"A tailored nightly roll-on helped a client notice calmer evenings when combined with a simple wind-down routine." — anonymized case note</div>
        <div style="background:var(--card);padding:12px;border-radius:10px">"Group participants found the scent-matching exercise helped them describe what they wanted from scent support."</div>
      </div>
    </section>

    <section style="padding:18px 28px">
      <h2>FAQ — Safety & Use</h2>
      <div class="faq">
        <div class="faq-item">
          <h4>Dilution and dosing</h4>
          <p>We provide dilution instructions for each blend and recommend conservative starting points. If uncertain, choose the lowest dilution and increase only with guidance.</p>
        </div>
        <div class="faq-item">
          <h4>Patch testing</h4>
          <p>Patch tests are advised for topical use. Apply a small amount on the inner forearm and observe for 24–48 hours for irritation.</p>
        </div>
        <div class="faq-item">
          <h4>Pets</h4>
          <p>Some oils can be problematic for animals. We always flag pet-safe blends and offer alternatives when households include animals.</p>
        </div>
        <div class="faq-item">
          <h4>Pregnancy & medical conditions</h4>
          <p>We avoid certain botanicals in pregnancy and advise consulting a healthcare provider. Our guidance does not replace medical advice.</p>
        </div>
      </div>
    </section>

  </main>
  <footer>
    <div>&copy; {{BUSINESS_NAME}} • <a href="contact.html">{{EMAIL}}</a></div>
    <div>Call: <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
  </footer>
</body>
</html>"} 
{"path":"blends.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Custom Blends</title>
  <style>
    :root{--bg:#fffdfb;--accent:#7aa27a;--muted:#666}
    body{font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:var(--bg);margin:0;color:#111}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 26px}
    .logo{width:48px;height:48px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#a0c6a0);display:grid;place-items:center;color:#fff;font-weight:800}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none}
    .hero{padding:26px;border-bottom:1px solid #eef4eb}
    .hero h1{margin:0;font-size:24px}
    .hero p{margin:6px 0 0 0;color:var(--muted)}

    .products{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:18px}
    .card{background:#fff;padding:14px;border-radius:10px;box-shadow:0 6px 18px rgba(20,30,15,0.04)}
    .name{font-weight:800}
    .desc{color:var(--muted);font-size:13px;margin-top:6px}
    .price{font-weight:900;font-size:20px;margin-top:12px}

    /* comparator toggle */
    .comparator{display:flex;align-items:center;gap:12px;padding:8px 0}
    .switch{width:52px;height:28px;background:#e9efe7;border-radius:20px;position:relative;cursor:pointer}
    .knob{width:24px;height:24px;background:white;border-radius:50%;position:absolute;top:2px;left:2px;box-shadow:0 3px 8px rgba(0,0,0,0.08);transition:left .28s}
    .switch.on{background:linear-gradient(90deg,var(--accent),#8cbf8c)}
    .switch.on .knob{left:26px}
    .label{font-size:13px;color:var(--muted)}

    /* responsive */
    @media(max-width:980px){.products{grid-template-columns:repeat(2,1fr)}}
    @media(max-width:640px){.products{grid-template-columns:1fr}}

    /* small numbers animation helper */
    .meta{font-size:13px;color:var(--muted);margin-top:8px}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">B</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">Custom scent compositions</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Compositions</a>
      <a href="shop.html">Shop</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <h1>Tailored blends for daily moments</h1>
      <p>Choose a composition and we'll provide dilution guidance, patch-test steps, and options for roll-ons, sprays, or diffuser-ready vials.</p>
      <div style="margin-top:12px;display:flex;align-items:center;justify-content:space-between">
        <div class="comparator" aria-hidden="true">
          <div class="label">Pricing view</div>
          <div id="priceSwitch" class="switch" role="button" aria-pressed="false"><div class="knob"></div></div>
          <div class="label" id="priceMode">Monthly</div>
        </div>
        <div style="font-size:13px;color:var(--muted)">Free consult for first-time clients with code: NEWSCENT</div>
      </div>
    </section>

    <section class="products" id="blendGrid">
      <div class="card" data-month="24" data-package="95">
        <div class="name">Calm Thread</div>
        <div class="desc">Soft woods and a hint of citrus to help navigate restless moments. 10 ml vial.</div>
        <div class="price">$<span class="num">24</span></div>
        <div class="meta">Monthly subscription or one-time package.</div>
      </div>

      <div class="card" data-month="22" data-package="85">
        <div class="name">Focus Loom</div>
        <div class="desc">Bright citrus over a grounding base; sized for a desk diffuser or roll-on.</div>
        <div class="price">$<span class="num">22</span></div>
        <div class="meta">Includes dilution instructions and patch-test protocol.</div>
      </div>

      <div class="card" data-month="28" data-package="110">
        <div class="name">Evening Ease</div>
        <div class="desc">Warm florals and soft balsam for a concise night routine.</div>
        <div class="price">$<span class="num">28</span></div>
        <div class="meta">Safe for most adults; pregnancy-safe alternatives available.</div>
      </div>

    </section>

    <section style="padding:18px">
      <h2 style="margin:0 0 8px 0">How the comparator works</h2>
      <p style="margin:0;color:var(--muted)">Toggle between a monthly subscription price and a single-package total. Numbers animate so changes are easy to follow.</p>
    </section>

    <section style="padding:18px">
      <h2 style="margin-top:0">Good to know</h2>
      <ul style="color:var(--muted)">
        <li>All blends include a label with suggested dilution and storage notes.</li>
        <li>We recommend patch testing on the inner forearm for topical use.</li>
        <li>If you have pets or are pregnant, tell us — we will suggest safe alternatives.</li>
      </ul>
    </section>

  </main>

  <script>
    // Pricing comparator: toggle monthly vs package with animated numbers
    (function(){
      const switchEl = document.getElementById('priceSwitch');
      const modeLabel = document.getElementById('priceMode');
      const cards = Array.from(document.querySelectorAll('#blendGrid .card'));
      let on = false; // false -> monthly view, true -> package

      function animateNumber(el, from, to, duration){
        const start = performance.now();
        const diff = to - from;
        function frame(time){
          const t = Math.min(1,(time - start)/duration);
          const val = Math.round(from + diff * (1 - Math.pow(1 - t,2))); // ease-out
          el.textContent = val;
          if(t < 1) requestAnimationFrame(frame);
        }
        requestAnimationFrame(frame);
      }

      function refreshPrices(){
        cards.forEach(card =>{
          const numEl = card.querySelector('.num');
          const from = parseInt(numEl.textContent,10);
          const to = parseInt(on ? card.getAttribute('data-package') : card.getAttribute('data-month'),10);
          animateNumber(numEl, from, to, 600);
        });
      }

      switchEl.addEventListener('click', ()=>{
        on = !on;
        switchEl.classList.toggle('on', on);
        switchEl.setAttribute('aria-pressed', String(on));
        modeLabel.textContent = on ? 'Package' : 'Monthly';
        refreshPrices();
      });

      // ensure initial values reflect monthly
      document.addEventListener('DOMContentLoaded', ()=>{
        cards.forEach(card=>{ const num = card.getAttribute('data-month'); card.querySelector('.num').textContent = num; });
      });
    })();
  </script>
</body>
</html>"} 
{"path":"shop.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Essentials Shop</title>
  <style>
    :root{--bg:#fbfff9;--accent:#5c9b5c;--muted:#5b6360}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:#111}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 22px}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none}
    .hero{padding:18px 22px;border-bottom:1px solid #eef3ea}
    .hero h1{margin:0;font-size:24px}
    .grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;padding:18px}
    .item{background:#fff;padding:12px;border-radius:10px;box-shadow:0 6px 18px rgba(20,30,15,0.04)}
    .item h4{margin:0}
    .price{font-weight:800;font-size:18px;margin-top:8px}

    /* proof gallery */
    .proof{padding:18px;border-top:1px dashed #e6efe2;background:linear-gradient(180deg,rgba(92,155,92,0.03),transparent)}
    .testimonial{display:flex;gap:12px;align-items:flex-start}
    .avatar{width:48px;height:48px;border-radius:12px;background:linear-gradient(135deg,#8fc58f,#eaf6ea);display:grid;place-items:center;font-weight:800}
    .quote{font-style:italic;color:var(--muted)}
    .badges{display:flex;gap:8px;margin-top:10px}
    .badge{background:white;padding:6px 8px;border-radius:8px;border:1px solid #e2efe0;cursor:help}
    .tooltip{position:absolute;background:#222;color:#fff;padding:6px 8px;border-radius:6px;font-size:13px;pointer-events:none;opacity:0;transform:translateY(-8px);transition:opacity .16s,transform .16s}

    /* responsive */
    @media(max-width:1100px){.grid{grid-template-columns:repeat(2,1fr)}}
    @media(max-width:640px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div style="width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#9bcf9b);display:grid;place-items:center;color:#fff;font-weight:800">S</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">Essentials for gentle scent work</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Essentials</a>
      <a href="book.html">Reserve</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <h1>Shop essentials — curated and safety-minded</h1>
      <p style="margin:6px 0 0 0;color:var(--muted)">Diffusers, roller kits, and small-batch blends. Clear usage instructions accompany every item.</p>
    </section>

    <section class="grid">
      <div class="item" data-month="8" data-package="32">
        <h4>Roll-on Starter (10ml)</h4>
        <div class="price">$<span class="num">8</span></div>
        <div style="color:var(--muted);font-size:13px;margin-top:8px">Pre-diluted, labeled, ready to use.</div>
      </div>

      <div class="item" data-month="6" data-package="24">
        <h4>Room Spray (50ml)</h4>
        <div class="price">$<span class="num">6</span></div>
        <div style="color:var(--muted);font-size:13px;margin-top:8px">Water-based blend with preservative system for home use.</div>
      </div>

      <div class="item" data-month="10" data-package="38">
        <h4>Mini Diffuser</h4>
        <div class="price">$<span class="num">10</span></div>
        <div style="color:var(--muted);font-size:13px;margin-top:8px">USB diffuser for desks and bedside tables.</div>
      </div>

      <div class="item" data-month="4" data-package="14">
        <h4>Patch-test Set</h4>
        <div class="price">$<span class="num">4</span></div>
        <div style="color:var(--muted);font-size:13px;margin-top:8px">Small sample vials for conservative testing.</div>
      </div>
    </section>

    <section class="proof">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <div>
          <h3 style="margin:0">Proof Gallery</h3>
          <div style="color:var(--muted);font-size:13px;margin-top:6px">Rotating testimonials and partner badges — browse experiences and credentials.</div>
        </div>
        <div style="font-size:13px;color:var(--muted)">Need help? <a href="contact.html">{{EMAIL}}</a></div>
      </div>

      <div id="proofRotator" style="margin-top:14px;display:flex;gap:14px;align-items:flex-start">
        <div class="testimonial" style="flex:1;gap:12px">
          <div class="avatar">C</div>
          <div>
            <div class="quote" id="tQuote">"The roll-on became part of my evening routine — subtle and steady."</div>
            <div style="margin-top:8px;color:var(--muted);font-size:13px">— Client, anonymous</div>
          </div>
        </div>
        <div style="min-width:220px">
          <div style="font-size:13px;color:var(--muted)">Credibility</div>
          <div class="badges" id="badges">
            <div class="badge" data-tip="Industry training in aromatics">Certified Training</div>
            <div class="badge" data-tip="Local business reviewed by community">Local Reviews</div>
            <div class="badge" data-tip="Safety-first protocols and documented patch-test procedures">Safety Protocols</div>
          </div>
        </div>
      </div>

      <div id="tooltip" class="tooltip"></div>
    </section>

    <section style="padding:18px">
      <h3 style="margin-top:0">Compare pricing quickly</h3>
      <div style="display:flex;align-items:center;gap:12px;margin-top:10px">
        <div style="font-size:13px;color:var(--muted)">View</div>
        <div id="shopSwitch" class="switch" style="width:52px;height:28px;background:#eef6ee;border-radius:20px;position:relative;cursor:pointer"><div id="shopKnob" style="width:24px;height:24px;background:#fff;border-radius:50%;position:absolute;top:2px;left:2px;box-shadow:0 3px 8px rgba(0,0,0,0.08);transition:left .28s"></div></div>
        <div style="font-size:13px;color:var(--muted)" id="shopMode">Monthly</div>
      </div>
    </section>

  </main>

  <script>
    // Proof gallery rotation + badge tooltips
    (function(){
      const quotes = [
        '"The roll-on became part of my evening routine — subtle and steady."',
        '"The small diffuser made my desk feel calmer; I like the gentle scent."',
        '"Clear instructions and safe dilution made me confident to try a new routine."'
      ];
      let idx = 0;
      const quoteEl = document.getElementById('tQuote');
      const tooltip = document.getElementById('tooltip');
      const badges = Array.from(document.querySelectorAll('.badge'));

      function rotate(){
        idx = (idx + 1) % quotes.length;
        quoteEl.style.opacity = 0; quoteEl.style.transition = 'opacity .28s';
        setTimeout(()=>{ quoteEl.textContent = quotes[idx]; quoteEl.style.opacity = 1; }, 300);
      }
      let rotTimer = setInterval(rotate, 6000);

      badges.forEach(b=>{
        b.addEventListener('mouseenter', (e)=>{
          const tip = b.getAttribute('data-tip');
          tooltip.textContent = tip;
          const rect = b.getBoundingClientRect();
          tooltip.style.left = (rect.left + window.scrollX) + 'px';
          tooltip.style.top = (rect.top + window.scrollY - 44) + 'px';
          tooltip.style.opacity = 1; tooltip.style.transform = 'translateY(0)';
        });
        b.addEventListener('mouseleave', ()=>{ tooltip.style.opacity = 0; tooltip.style.transform = 'translateY(-8px)'; });
        b.addEventListener('focus', ()=>{});
      });

      // Pause rotation when tooltip is visible
      ['mouseenter','focus'].forEach(ev => badges.forEach(b=>b.addEventListener(ev, ()=>clearInterval(rotTimer))));
      ['mouseleave','blur'].forEach(ev => badges.forEach(b=>b.addEventListener(ev, ()=>rotTimer = setInterval(rotate,6000))));

      // Shop pricing comparator (animates numbers)
      const items = Array.from(document.querySelectorAll('.item'));
      const shopSwitch = document.getElementById('shopSwitch');
      const shopKnob = document.getElementById('shopKnob');
      const shopMode = document.getElementById('shopMode');
      let shopOn = false;

      function animateNumber(el, from, to, duration){
        const start = performance.now();
        const diff = to - from;
        function frame(time){
          const t = Math.min(1,(time - start)/duration);
          const val = Math.round(from + diff * (1 - Math.pow(1 - t,2)));
          el.textContent = val;
          if(t < 1) requestAnimationFrame(frame);
        }
        requestAnimationFrame(frame);
      }

      shopSwitch.addEventListener('click', ()=>{
        shopOn = !shopOn;
        shopKnob.style.left = shopOn ? '26px' : '2px';
        shopMode.textContent = shopOn ? 'Package' : 'Monthly';
        items.forEach(it=>{
          const numEl = it.querySelector('.num');
          const from = parseInt(numEl.textContent,10);
          const to = parseInt(shopOn ? it.getAttribute('data-package') : it.getAttribute('data-month'),10);
          animateNumber(numEl, from, to, 500);
        });
      });

      // Initialize numbers to monthly
      document.addEventListener('DOMContentLoaded', ()=>{
        items.forEach(it=>{ it.querySelector('.num').textContent = it.getAttribute('data-month'); });
      });
    })();
  </script>

